#[derive(Clone)]struct Model<const K:usize>{row:CompactRow,state:Option<EntityRuntimeState>}
impl<const K:usize> TeaqlEntity for Model<K>{const ENTITY_NAME:&'static str=if K==0{"Parent"}else if K==1{"Child"}else{"Leaf"};fn entity_descriptor()->EntityDescriptor{EntityDescriptor::new(Self::ENTITY_NAME)}}
impl<const K:usize> Entity for Model<K>{fn from_compact_row(row:CompactRow)->Result<Self,EntityError>{if row.get("fail").and_then(Value::try_bool).unwrap_or(false){Err(EntityError::new(Self::ENTITY_NAME,"model decode failed"))}else{Ok(Self{row,state:None})}}fn into_values(self)->MutationValues{self.row.into_map().into()}fn on_loaded(&mut self,context:&dyn std::any::Any){if let Some(root)=context.downcast_ref::<EntityRuntimeState>(){let mut state=root.clone();state.set_original_compact_row(Self::ENTITY_NAME,self.row.clone());self.state=Some(state);}}}
impl<const K:usize> IdentifiableEntity for Model<K>{fn id_value(&self)->Value{self.row.get("id").cloned().unwrap_or(Value::Null)}}
// Only the private Context decoder calls are bridged. The real registry and
// real Context metadata/telemetry APIs execute the pinned implementations.
struct UserContext{inner:teaql_runtime::UserContext,registry:InMemoryEntityGraphDecoderRegistry}
impl std::ops::Deref for UserContext{type Target=teaql_runtime::UserContext;fn deref(&self)->&Self::Target{&self.inner}}
impl UserContext{
 fn decode_compact_entity_into_graph(&self,e:&str,row:CompactRow,root:&EntityRuntimeState,graph:&mut EntityGraphBuilder)->Result<(),EntityError>{self.registry.decode_compact(e,row,root,graph)}
 fn decode_compact_entity_batch_into_graph(&self,e:&str,rows:Vec<CompactRow>,root:&EntityRuntimeState,graph:&mut EntityGraphBuilder)->Result<(),EntityError>{self.registry.decode_compact_batch(e,rows,root,graph)}
 fn decode_compact_entity_list_into_graph(&self,e:&str,rows:Vec<CompactRow>,root:&EntityRuntimeState,graph:&mut EntityGraphBuilder,owner:&str,id:u64,name:&str)->Result<(),EntityError>{self.registry.decode_compact_list(e,rows,root,graph,owner,id,name)}
 fn decode_compact_entity_option_into_graph(&self,e:&str,rows:Vec<CompactRow>,root:&EntityRuntimeState,graph:&mut EntityGraphBuilder,owner:&str,id:u64,name:&str)->Result<(),EntityError>{self.registry.decode_compact_option(e,rows,root,graph,owner,id,name)}
}
struct Mock{probes:bool,calls:Mutex<usize>}impl DataServiceExecutor for Mock{type Error=io::Error;fn capabilities(&self)->DataServiceCapabilities{*self.calls.lock().unwrap()+=1;DataServiceCapabilities{small_parent_relation_probes:self.probes,..Default::default()}}}
impl QueryExecutor for Mock{async fn query(&self,_:QueryRequest)->Result<QueryResult,Self::Error>{panic!("bypassed entity fetch")}}impl MutationExecutor for Mock{async fn mutate(&self,_:MutationRequest)->Result<MutationResult,Self::Error>{panic!("unused")}}
struct Metadata<'a>{context:&'a UserContext}impl Metadata<'_>{fn entity(&self,e:&str)->Option<&EntityDescriptor>{self.context.entity(e)}fn capture_execution_metadata(&self)->bool{self.context.sql_log_options().select}}
struct ContextDataService<'a,E>{metadata:Metadata<'a>,executor:&'a E}
#[derive(Default)]struct State{events:Mutex<Vec<String>>,depth:AtomicUsize,calls:Mutex<Vec<J>>,drops:AtomicUsize}
impl State{fn note(&self,event:&str,name:&str,extra:Option<&str>){self.events.lock().unwrap().push(match extra{Some(extra)=>format!("{event}:{name}:{extra}"),None=>format!("{event}:{name}")});}}
struct Scope{state:Arc<State>,name:String}impl Drop for Scope{fn drop(&mut self){self.state.note("drop",&self.name,None);}}
struct Leave<'a>(&'a Scope);impl Drop for Leave<'_>{fn drop(&mut self){self.0.state.depth.fetch_sub(1,Ordering::SeqCst);self.0.state.note("leave",&self.0.name,None);}}
impl RuntimeTelemetryScope for Scope{fn with_context(&self,cb:&mut dyn FnMut()){self.state.note("enter",&self.name,None);self.state.depth.fetch_add(1,Ordering::SeqCst);let _leave=Leave(self);cb();}fn success(&mut self,a:BTreeMap<String,RuntimeAttributeValue>){let RuntimeAttributeValue::Integer(n)=a["teaql.result.cardinality"] else{panic!("attribute")};self.state.note("success",&self.name,Some(&n.to_string()));}fn failure(&mut self,e:&str){self.state.note("failure",&self.name,Some(e));}}
struct Telemetry(Arc<State>);impl RuntimeTelemetry for Telemetry{fn start(&self,op:RuntimeOperation)->Box<dyn RuntimeTelemetryScope>{self.0.note("start",&op.name,None);Box::new(Scope{state:self.0.clone(),name:op.name})}}
struct EntityDataService<'a,E:DataServiceExecutor>{data_service:ContextDataService<'a,E>,trace_context:Vec<TraceNode>,state:&'a State,input:&'a J,error:fn(&str)->E::Error}
impl<'a,E:DataServiceExecutor> EntityDataService<'a,E>{
 fn scoped_data_service_internal(&self,_:String)->Self{Self{data_service:ContextDataService{metadata:Metadata{context:self.data_service.metadata.context},executor:self.data_service.executor},trace_context:vec![],state:self.state,input:self.input,error:self.error}}
 fn with_trace_context(mut self,t:Vec<TraceNode>)->Self{self.trace_context=t;self}
 async fn fetch_compact_all_internal(&self,q:SelectQuery)->Result<Vec<CompactRow>,DataServiceError<E::Error>>{
  let call=json!({"entity":q.entity,"depth":self.state.depth.load(Ordering::SeqCst),"trace":self.trace_context.iter().map(|t|json!({"entity":t.entity_type,"comment":t.comment})).collect::<Vec<_>>(),"relations":q.relations.iter().map(|l|l.name.clone()).collect::<Vec<_>>()});self.state.calls.lock().unwrap().push(call);let index=self.state.calls.lock().unwrap().len();let _drop=DropWork(self.state);Delay(self.input["pending"].as_u64().unwrap()).await;
  if index==self.input["fail_at"].as_u64().unwrap() as usize{return Err(DataServiceError::Executor((self.error)("fetch failed")))}Ok(items(self.input,"responses").get(index-1).map(|r|rows(r.as_array().unwrap())).unwrap_or_default())
 }
}
struct DropWork<'a>(&'a State);impl Drop for DropWork<'_>{fn drop(&mut self){self.0.drops.fetch_add(1,Ordering::SeqCst);}}
struct Delay(u64);impl Future for Delay{type Output=();fn poll(mut self:Pin<&mut Self>,cx:&mut Context<'_>)->Poll<()>{if self.0>0{self.0-=1;cx.waker().wake_by_ref();Poll::Pending}else{Poll::Ready(())}}}
mod locked{use super::*;include!(concat!(env!("OUT_DIR"),"/relation_hydration.rs"));
 pub async fn run(repo:&EntityDataService<'_,Mock>,parents:&mut [CompactRow],plans:&[RelationLoadPlan],root:&EntityRuntimeState,graph:&mut EntityGraphBuilder,mode:&str)->Result<(),DataServiceError<io::Error>>{match mode{"embedded"=>{for plan in plans{repo.enhance_plan(parents,plan).await?}Ok(())},"flat"=>repo.hydrate_flat_plans_internal(parents,plans,root,graph).await,_=>repo.hydrate_compact_flat_plans_internal(parents,plans,root,graph).await}}
 pub fn attach(repo:&EntityDataService<'_,Mock>,parents:&mut [CompactRow],plan:&RelationLoadPlan,children:Vec<CompactRow>){repo.attach_relation_rows(parents,plan,children)}
 pub fn install(repo:&EntityDataService<'_,Mock>,parents:&[CompactRow],plan:&RelationLoadPlan,children:Vec<CompactRow>,root:&EntityRuntimeState,graph:&mut EntityGraphBuilder)->Result<(),DataServiceError<io::Error>>{repo.install_compact_flat_relation(parents,plan,children,root,graph)}
}
fn items<'a>(j:&'a J,k:&str)->&'a [J]{j[k].as_array().map(Vec::as_slice).unwrap_or(&[])}
fn rows(j:&[J])->Vec<CompactRow>{j.iter().map(|r|CompactRow::from_map(r.as_object().unwrap().iter().map(|(k,v)|(k.clone(),fixture_value::value(v))).collect())).collect()}
fn row_out(r:&CompactRow)->J{json!(r.clone().into_map().iter().map(|(k,v)|(k.clone(),format!("{v:?}"))).collect::<BTreeMap<_,_>>())}
fn plan(j:&J,parent:&str)->RelationLoadPlan{let target=j["target"].as_str().unwrap();RelationLoadPlan{parent_entity:parent.into(),relation_name:j["name"].as_str().unwrap().into(),path:j["name"].as_str().unwrap().into(),target_entity:target.into(),local_key:j["local"].as_str().unwrap().into(),foreign_key:j["foreign"].as_str().unwrap().into(),many:j["many"]==true,query:j.get("query").map(|v|{let mut q=fixture_sql::query(v);q.top_n_probe_parent_threshold=v["threshold"].as_u64().map(|n|n as usize);q.relations=items(v,"relations").iter().map(|n|RelationLoad::new(n.as_str().unwrap())).collect();q}),children:items(j,"children").iter().map(|p|plan(p,target)).collect()}}
struct Noop;impl Wake for Noop{fn wake(self:Arc<Self>){}}
fn drive(f:impl Future<Output=Result<(),DataServiceError<io::Error>>>,polls:u64)->J{let mut f=Box::pin(f);let waker=Waker::from(Arc::new(Noop));let mut cx=Context::from_waker(&waker);for _ in 0..polls{if let Poll::Ready(r)=f.as_mut().poll(&mut cx){return match r{Ok(())=>json!({}),Err(e)=>json!({"error":e.to_string()})}}}json!({"cancelled":true})}
fn inspect<const K:usize>(root:&EntityRuntimeState,names:&BTreeSet<String>,entities:&mut Vec<J>,relations:&mut Vec<J>,states:&mut Vec<EntityRuntimeState>){
 fn model<const K:usize>(m:&Model<K>,states:&mut Vec<EntityRuntimeState>)->J{if let Some(s)=&m.state{states.push(s.clone())}row_out(&m.row)}
 for id in 0..=32{if let Some(m)=root.resolve_entity::<Model<K>>(id){entities.push(json!({"kind":K,"id":id,"row":model(m,states)}));}for owner in ["Parent","Child","Leaf"]{for name in names{let list=root.resolve_relation_list::<Model<K>>(owner,id,name);let optional=root.resolve_relation_option::<Model<K>>(owner,id,name);if list.is_none() && optional.is_none(){continue}let mut item=json!({"kind":K,"owner":owner,"id":id,"name":name,"mode":if list.is_some(){"list"}else{"option"}});item["rows"]=if let Some(list)=list{item["loaded"]=json!(list.is_loaded);json!(list.as_slice().iter().map(|m|model(m,states)).collect::<Vec<_>>())}else{optional.unwrap().as_ref().map(|m|model(m,states)).unwrap_or(J::Null)};relations.push(item);}}}
}
fn evaluate(j:&J)->J{let state=Arc::new(State::default());let mut module=RuntimeModule::new();for name in ["Parent","Child","Leaf"]{let mut e=EntityDescriptor::new(name);let mut id=PropertyDescriptor::new("id",DataType::U64);id.is_id=true;e.properties.push(id);for m in items(j,"metadata"){if m["entity"]==name{let mut r=RelationDescriptor::new(m["name"].as_str().unwrap(),m["target"].as_str().unwrap());r.local_key=m["local"].as_str().unwrap().into();r.foreign_key=m["foreign"].as_str().unwrap().into();r.many=m["many"]==true;e.relations.push(r)}}module=module.descriptor(e)}let mut registry=InMemoryEntityGraphDecoderRegistry::default();for name in items(j,"register"){match name.as_str().unwrap(){"Parent"=>registry.register::<Model<0>>(),"Child"=>registry.register::<Model<1>>(),_=>registry.register::<Model<2>>()}}let context=UserContext{inner:module.into_context().with_runtime_telemetry(Arc::new(Telemetry(state.clone()))),registry};let mock=Mock{probes:j["probes"]==true,calls:Mutex::new(0)};let repo=EntityDataService{data_service:ContextDataService{metadata:Metadata{context:&context},executor:&mock},trace_context:vec![TraceNode::typed(TraceKind::Request,"Parent",None,"root request")],state:&state,input:j,error:|s|io::Error::other(s.to_owned())};let mut parents=rows(items(j,"parents"));let plans=items(j,"plans").iter().map(|p|plan(p,"Parent")).collect::<Vec<_>>();let root=EntityRuntimeState::default();let mut graph=EntityGraphBuilder::default();let mode=j["mode"].as_str().unwrap();
 let mut out=if mode=="attach" || mode=="install"{let children=items(j,"responses").first().map(|r|rows(r.as_array().unwrap())).unwrap_or_default();if mode=="attach"{locked::attach(&repo,&mut parents,&plans[0],children);json!({})}else{match locked::install(&repo,&parents,&plans[0],children,&root,&mut graph){Ok(())=>json!({}),Err(e)=>json!({"error":match e{DataServiceError::Entity(e)=>e.to_string(),e=>e.to_string()}})}}}else{drive(locked::run(&repo,&mut parents,&plans,&root,&mut graph,mode),j["polls"].as_u64().unwrap())};out["parents"]=json!(parents.iter().map(row_out).collect::<Vec<_>>());out["entity_count"]=json!(graph.entity_count());out["relation_count"]=json!(graph.relation_list_count());assert!(root.freeze_graph(graph).is_ok());let mut names=BTreeSet::new();fn collect(p:&RelationLoadPlan,names:&mut BTreeSet<String>){names.insert(p.relation_name.clone());for child in &p.children{collect(child,names)}}for p in &plans{collect(p,&mut names)}for m in items(j,"metadata"){names.insert(m["name"].as_str().unwrap().into());}let(mut entities,mut relations,mut states)=(vec![],vec![],vec![]);inspect::<0>(&root,&names,&mut entities,&mut relations,&mut states);inspect::<1>(&root,&names,&mut entities,&mut relations,&mut states);inspect::<2>(&root,&names,&mut entities,&mut relations,&mut states);out["entities"]=json!(entities);out["relations"]=json!(relations);out["ledger"]=json!(states.iter().enumerate().map(|(i,s)|states[..i].iter().position(|other|other==s).unwrap_or(i)).collect::<Vec<_>>());out["calls"]=json!(*state.calls.lock().unwrap());out["drops"]=json!(state.drops.load(Ordering::SeqCst));out["capabilities"]=json!(*mock.calls.lock().unwrap());out["events"]=json!(*state.events.lock().unwrap());out["depth"]=json!(state.depth.load(Ordering::SeqCst));out}
fn main(){for line in io::stdin().lock().lines(){println!("{}",evaluate(&serde_json::from_str::<J>(&line.unwrap()).unwrap()));}}
